#include "tactical_motion_internal.hpp"
#include "tactical_frames.hpp"
#include <algorithm>
#include <cmath>
#include <numbers>
namespace transartica::panels {
using namespace visual;
void TacticalMotion::draw(TacticalScreen&scene,const combat::Tactical&battle){auto&i=*impl_;for(const auto&[id,a]:battle.snapshot().actors)if(!i.tracks.contains(id)){auto t=std::make_shared<Impl::Track>();t->actor=a;t->target={double(a.x),double(a.y)};t->roof=a.roof;t->count=t->alive=a.count;i.muster(*t,a,false);i.tracks[id]=std::move(t);}
    auto pose=[&](const art::AtlasFrame&f,const std::filesystem::path&path,Point foot,double facing,SDL_Color tint,bool offset=false){const double x=offset?(facing<0?(-f.pivot.x-f.crop.w)/4:f.pivot.x/4):(facing<0?(f.pivot.x-f.crop.w)/4:-f.pivot.x/4),y=offset?f.pivot.y/4:-f.pivot.y/4;scene.picture(path,f.crop,{float(foot.x+x),float(foot.y+y),f.crop.w/4.f,f.crop.h/4.f},tint,facing<0);};
    auto beast=[&](int side,int count,int motion,int index,Point foot,double facing,int riders,SDL_Color tint){const int variant=count<=1?0:side==0?1:2;const auto&frames=art::mammoth_body[variant][motion];index=std::clamp(index,0,int(frames.size())-1);pose(frames[index],scene.assets_/"combat/mammoth-poses.png",foot,facing,tint);if(variant&&riders>0){const auto&parts=art::mammoth_riders[side][motion][index];for(std::size_t p=0;p<parts.size();++p){if(riders==1&&parts.size()>1&&p==0)continue;pose(parts[p],scene.assets_/"combat/mammoth-poses.png",foot,facing,tint,true);}}};
    auto rider=[&](int side,int which,double dt,int beast_motion,int beast_index,int launched,Point at,double facing,bool pair,SDL_Color tint){const auto&chair=art::mammoth_riders[side][1][0][which];const double seatx=(chair.pivot.x+chair.crop.w/2.)/4-art::mammoth_seat[side][1][0].x/4;const Point rim=art::mammoth_seat[side][beast_motion][launched]*.25;const Point launch{rim.x+seatx-3,rim.y},start=launch+Point{0,3};dt=std::max(0.,dt);if(dt<.44){const int frame=dt<.12?0:dt<.24?1:2,motion=frame<2?3:4,index=frame<2?frame:0;const auto&parts=art::mammoth_riders[side][motion][index];auto part=parts[std::min(which,int(parts.size())-1)];part.pivot=part.pivot+art::mammoth_seat[side][beast_motion][beast_index]-art::mammoth_seat[side][motion][index];pose(part,scene.assets_/"combat/mammoth-poses.png",at,facing,tint,true);return;}const double flight=dt-.44,total=(24+std::sqrt(24*24-2*200*start.y))/200;Point point;int frame;const bool lying=flight>=total;if(!lying){frame=flight<.12?0:flight<.3?1:2;point={start.x-11*flight,start.y-24*flight+.5*200*flight*flight};}else{const double settle=std::min((flight-total)/.1,1.);point={start.x-11*total-.8*settle,-.8*std::sin(std::numbers::pi*settle)};frame=3;}const Point foot=at+Point{point.x*facing,point.y};if(lying&&!pair){pose(art::trooper_poses[3][side].back(),scene.assets_/"combat/trooper-poses.png",foot,facing,tint);return;}const int image=pair?frame+1:lying?4:2+std::min(frame,1);pose(art::mammoth_riders[side][4][std::clamp(image,1,4)][0],scene.assets_/"combat/mammoth-poses.png",foot,facing,tint,true);};
    auto crate=[&](Point foot,bool lit){const Point p=foot+Point{-1.75,-2.5};box(scene.canvas_,p-Point{.25,.25},{4,3},color(0x140d08));box(scene.canvas_,p,{3.5,2.5},color(0x6b4526));box(scene.canvas_,p,{3.5,.5},color(0x8c5d34));for(double x:{.75,2.5})box(scene.canvas_,p+Point{x,0},{.25,2.5},color(0x7d858d));const auto tip=p+Point{2.75,-1.25};line(scene.canvas_,p+Point{2,0},tip,.25,color(0xd8cfb4));if(lit){const double flicker=double((battle.snapshot().ticks*7)%5)/4;box(scene.canvas_,tip-Point{.25,.25},{.5,.5},lerp({1,.85,.4,1},{1,.45,.1,1},flicker));if(battle.snapshot().ticks%3==0)box(scene.canvas_,tip+Point{.25+flicker*.5,-.5-flicker*.5},{.25,.25},{1,.95,.6,1});}};
    struct Item{Point at;double depth{};Impl::Track*track{};Impl::Soldier*soldier{};Impl::Body*body{};const combat::Charge*charge{};};std::vector<Item>items;
    for(auto&[id,t]:i.tracks)for(auto&s:t->soldiers){const Point at=i.point(scene,battle,*t,s);if(s.board){const auto&b=*s.board;const double time=b.t-b.dismount;if(!b.hop&&b.wagon>=0&&time>=b.run&&time<b.run+b.climb+.01){const auto top=i.place(scene,battle,t->roof,s.cell,i.offset(*t,s));const double edge=top.x+b.ladder,cap=i.roof_y(scene,battle,t->roof,b.wagon,edge,0),landing=i.roof_y(scene,battle,t->roof,b.wagon,top.x+b.land,0),bottom=landing+b.height;const auto g=scene.wagon(battle,t->roof,b.wagon);const auto iron=scene.materials_.iron(g.sprite->path,g.sprite->region);const Color tint{iron.r/255.,iron.g/255.,iron.b/255.,1};box(scene.canvas_,{edge+(b.out>0?0:-.5),cap-1.5},{.5,bottom-(cap-1.5)},tint);for(int rung=0;rung<=b.rungs;++rung){const double y=cap+8.8+rung*b.rung;box(scene.canvas_,{b.out>0?edge:edge-2.5,y-.25},{2.5,.5},tint);}}}items.push_back({at,at.y,t.get(),&s,nullptr,nullptr});}
    for(auto&body:i.bodies){const auto at=i.place(scene,battle,body.roof,body.cell,body.offset);items.push_back({at,at.y+(body.fall&&body.t>=body.delay?.5:0),nullptr,nullptr,&body,nullptr});}for(const auto&c:battle.snapshot().charges){const auto state=i.charges.find({c.side,c.slot});if(state!=i.charges.end()&&!state->second.placed)continue;const auto at=i.place(scene,battle,c.side,{double(c.slot),0});items.push_back({at,at.y,nullptr,nullptr,nullptr,&c});}std::stable_sort(items.begin(),items.end(),[](const Item&a,const Item&b){return a.depth<b.depth;});
    for(auto&item:items){if(item.charge){const auto state=i.charges.find({item.charge->side,item.charge->slot});crate(item.at,state==i.charges.end()||state->second.lit);continue;}if(item.body){auto&b=*item.body;const double fading=b.fall?b.t-(b.delay+b.span+3):b.t,alpha=std::clamp(1-fading/.6,0.,1.);const SDL_Color tint{255,255,255,Uint8(std::round(alpha*255))};if(b.rider>=0){rider(b.side,b.rider,b.t-b.delay,1,0,0,item.at,b.facing,b.pair,tint);continue;}if(b.mammoth){const int variant=b.count<=1?0:b.side==0?1:2,motion=b.t<b.delay?1:4,index=motion==1?0:int(std::floor(std::clamp((b.t-b.delay)/b.span,0.,1.)*(art::mammoth_body[variant][4].size()-1)+.5));beast(b.side,b.count,motion,index,item.at,b.facing,b.t<b.delay?std::clamp(b.count-1,0,2):0,tint);if(motion==4){const int seated=std::clamp(b.count-1,0,2),launched=int(std::floor(std::clamp(.44/b.span,0.,1.)*(art::mammoth_body[variant][4].size()-1)+.5));if(seated>0)rider(b.side,seated==1?1:0,b.t-b.delay,4,index,launched,item.at,b.facing,seated==2,tint);}}else if(b.fall&&b.t>=b.delay){const int family=b.kind==1?2:3;const auto&frames=art::trooper_poses[family][b.side];const int index=int(std::floor(std::clamp((b.t-b.delay)/.9/.85,0.,1.)*(frames.size()-1)+.5));pose(frames[index],scene.assets_/"combat/trooper-poses.png",item.at,b.facing,tint);}else{double crouch=0;if(b.fall){const int family=b.kind==1?2:3;crouch=i.matched(scene,b.side,-art::trooper_poses[family][b.side][0].pivot.y/4);}scene.soldier(item.at,b.side,float(b.facing),0,0,crouch,0,0,0,b.breath,tint);}continue;}
        auto&t=*item.track;auto&s=*item.soldier;const double facing=s.face!=0?s.face:t.facing;const auto&a=t.actor;const double hit=s.recoil/.35*.7;const SDL_Color tint{255,Uint8(std::round(std::clamp(1-.5*hit,0.,1.)*255)),Uint8(std::round(std::clamp(1-.55*hit,0.,1.)*255)),255};if(a.mammoth){int motion=1,index=0;if(s.recoil>0){motion=3;index=s.recoil>s.recoil_len*.5?0:1;}else if(s.strike>0){motion=2;index=std::min(3,int((1-s.strike/s.strike_len)*4));}else if(s.gait>=0){motion=0;index=s.gait;}else if(s.halt>0)index=.7-s.halt>=.15?1:0;int seated=a.count+i.waiting(t),dying=0;for(int uid:t.dying)for(const auto&body:i.bodies)if(body.uid==uid&&body.t<body.delay+body.span)dying=3;beast(a.side,seated+dying,motion,index,item.at,facing,std::clamp(seated-1,0,2),tint);continue;}
        if(s.board&&s.board->t<s.board->dismount){if(s.board->t>=0){const auto b=i.board_pose(scene,battle,t,s);pose(art::mammoth_dismount[a.side][std::clamp(b.dismount,0,4)],scene.assets_/"combat/mammoth-poses.png",item.at,s.board->face,tint);}continue;}
        double crouch=s.crouch,amp=s.amp,climb=0;int family=1,frame=s.plant;if(s.board){const auto b=i.board_pose(scene,battle,t,s);crouch=b.crouch;climb=b.climb;if(b.amp>=0)amp=b.amp;family=0;frame=b.frame;}const bool carrying=s.task&&i.charges.contains(s.task->key)&&!i.charges[s.task->key].placed;
        if(frame>=0){pose(art::trooper_poses[family][a.side][frame],scene.assets_/"combat/trooper-poses.png",item.at,facing,tint);if(carrying&&!s.board)crate(item.at+Point{facing*(3.76+1.75),0},false);}else{const double strike=s.strike>0?1-s.strike/.35:0;scene.soldier(item.at,a.side,float(facing),s.phase,float(amp),crouch,strike,s.recoil/.35,climb,s.breath,tint);if(carrying){const double low=std::min(crouch,1.);crate(item.at+Point{facing*(2+1.5*low),-5.5+3.5*low},false);}}
    }
    for(const auto&label:i.labels(scene,battle,false))scene.label(label.shown,label.text,label.size,label.anchor);for(const auto&[id,a]:battle.snapshot().actors)if(id==scene.selected_actor_){const auto at=point(scene,battle,a);scene.fill({float(at.x)-6,float(at.y)+6,12,1},{238,202,136,255});}
}
}
